using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
namespace MediaReviewer {
    public sealed class SourceRoot {
        public string Id {get;set;} public string Path {get;set;} public string RecordedPath {get;set;} public string ConnectionId {get;set;}
        public string Label {get{return Path+" | "+Id;}}
    }
    public sealed class SourceRootPage {public List<SourceRoot> Rows=new List<SourceRoot>();public string Next="";public bool HasMore;internal long Cost {get{return 512+Next.Length*2L+Rows.Sum(x=>128L+2L*(x.Id.Length+x.Path.Length+x.RecordedPath.Length+x.ConnectionId.Length));}}}
    public sealed class SourceCheckRow {public string Path {get;set;}public string State {get;set;}public string Error {get;set;}}
    public sealed class SourceConnection {
        public string Id,RootId,Path,State;public long Total,Full,Candidates,Missing,Failed;
        public List<SourceCheckRow> Rows=new List<SourceCheckRow>();
        internal long Cost {get{return 1024+2L*(Id.Length+RootId.Length+Path.Length+State.Length)+Rows.Sum(x=>128L+2L*(x.Path.Length+x.State.Length+x.Error.Length));}}
    }
    public static partial class Catalog {
        internal const string ConnectionEligible="o.superseded=0 AND (EXISTS(SELECT 1 FROM review_groups g WHERE g.root_id=o.root_id AND g.content_id=o.content_id AND g.retired=0 AND g.status<>'EVIDENCE' AND NOT EXISTS(SELECT 1 FROM resolved_locations l JOIN identity_runs r ON r.id=l.run_id WHERE l.occurrence_id=o.id AND r.state='published')) OR EXISTS(SELECT 1 FROM resolved_locations l JOIN identity_runs r ON r.id=l.run_id AND r.state='published' JOIN identity_plan p ON p.run_id=l.run_id AND p.digest=l.digest JOIN review_groups g ON g.id=p.group_id AND g.retired=0 AND g.status<>'EVIDENCE' WHERE l.occurrence_id=o.id))";
        // The rowid range advances once through the recorded collection; do not sort it for each file.
        internal const string ConnectionNextSql="SELECT o.rowid,o.id,o.content_id,o.path,o.size,o.modified_ticks,o.file_identity FROM occurrences o NOT INDEXED JOIN source_connections s ON s.id=? WHERE o.root_id=s.root_id AND o.rowid>s.cursor AND o.rowid<=s.ceiling AND "+ConnectionEligible+" ORDER BY o.rowid LIMIT 1";
        internal const string ConnectionIdentitySql="SELECT c.algorithm,c.algorithm_version,c.digest,c.sampling,c.size FROM contents c WHERE c.id IN(SELECT g.content_id FROM review_groups g WHERE g.root_id=?1 AND g.content_id=?2 AND g.retired=0 AND g.status<>'EVIDENCE' AND NOT EXISTS(SELECT 1 FROM resolved_locations l JOIN identity_runs r ON r.id=l.run_id WHERE l.occurrence_id=?3 AND r.state='published') UNION SELECT g.content_id FROM resolved_locations l JOIN identity_runs r ON r.id=l.run_id AND r.state='published' JOIN identity_plan p ON p.run_id=l.run_id AND p.digest=l.digest JOIN review_groups g ON g.id=p.group_id AND g.retired=0 AND g.status<>'EVIDENCE' WHERE l.occurrence_id=?3) LIMIT 2";
        internal static SourceConnection ConnectionStatus(SqliteConnection db,string id,bool details=true){
            var data=db.Query("SELECT id,root_id,path,state,total,full_count,candidate_count,missing_count,failed_count FROM source_connections WHERE id=?",new object[]{id},1);if(data.Count==0)throw new InvalidOperationException("This source check is unavailable; refresh Sources.");var v=data[0];var result=new SourceConnection {Id=(string)v[0],RootId=(string)v[1],Path=(string)v[2],State=(string)v[3],Total=(long)v[4],Full=(long)v[5],Candidates=(long)v[6],Missing=(long)v[7],Failed=(long)v[8]};
            if(details)foreach(var r in db.Query("SELECT substr(path,1,32767),state,error FROM source_connection_files WHERE connection_id=? ORDER BY rowid DESC LIMIT 20",new object[]{id},20))result.Rows.Add(new SourceCheckRow {Path=(string)r[0],State=(string)r[1],Error=(string)r[2]});return result;
        }
        internal static SourceRootPage SourceRoots(SqliteConnection db,string after){
            var result=new SourceRootPage();foreach(var row in db.Query("SELECT r.id,substr(s.path,1,32767),substr(r.path,1,32767),COALESCE((SELECT id FROM source_connections c WHERE c.root_id=r.id AND c.state IN('checking','interrupted','ready','discarding') ORDER BY created_at DESC LIMIT 1),h.connection_id,'') FROM roots r JOIN source_roots s ON s.id=r.id LEFT JOIN root_source_heads h ON h.root_id=r.id WHERE r.id>? COLLATE BINARY ORDER BY r.id COLLATE BINARY LIMIT 11",new object[]{after},11)){
                if(result.Rows.Count==10){result.HasMore=true;break;}string id=(string)row[0];if(id.Length>4096)throw new InvalidDataException("A saved root identifier exceeds the source manager limit; its data is preserved.");result.Rows.Add(new SourceRoot {Id=id,Path=(string)row[1],RecordedPath=(string)row[2],ConnectionId=(string)row[3]});result.Next=id;
            }return result;
        }
    }
    public sealed partial class ReviewerEngine {
        bool sourceConnectionBusy;
        object OwnSourceConnection(Func<object> body){lock(scanGate){if(reportActive || (scan!=null && !scan.Finished))throw new InvalidOperationException("Cancel the scan and wait for its owned workers before reconnecting sources.");sourceConnectionBusy=true;}try{return body();}finally{lock(scanGate)sourceConnectionBusy=false;}}
        static string ConnectionId(string id){Guid value;if(!Guid.TryParseExact(id,"N",out value))throw new ArgumentException("Invalid source check identifier");return value.ToString("N");}
        string QueueSourceRead(string kind,Func<SqliteConnection,object> body,long cost=2048){
            if(!ready || closing || faulted)throw new InvalidOperationException("Database is not ready");string id=Guid.NewGuid().ToString("N");var work=new DbWork {Body=body,Done=value=>Respond(new UiResult {Kind=kind,RequestId=id,Success=true,SourceConnection=value as SourceConnection,SourceRoots=value as SourceRootPage}),Failed=error=>Respond(new UiResult {Kind=kind,RequestId=id,Error=error.Message})};if(!reads.TryAdd(work,cost))throw new InvalidOperationException("Source reader is busy; refresh shortly.");return id;
        }
        public string RequestSourceRoots(string after=""){if(after==null || after.Length>4096)throw new ArgumentException("Invalid source page cursor");return QueueSourceRead("SourceRoots",db=>Catalog.SourceRoots(db,after),2048+after.Length*2L);}
        public string RequestSourceConnectionStatus(string id){id=ConnectionId(id);return QueueSourceRead("SourceConnectionStatus",db=>Catalog.ConnectionStatus(db,id));}
        public string RequestRootRemap(string rootId,string newPath,bool acceptMismatch){
            if(String.IsNullOrEmpty(rootId) || rootId.Length>4096)throw new ArgumentException("Select a recorded source root");string path=Catalog.PreviewSourcePath(newPath,"source-check");path=Path.GetDirectoryName(path);string id=Guid.NewGuid().ToString("N");
            // Acceptance is a separate, reviewable action after all check results are available.
            return EnqueueOperationWithId("SourceCheck",(db,t,p)=>OwnSourceConnection(()=>CheckConnection(db,id,rootId,path,t,p)),4096+2L*(path.Length+rootId.Length),null,id);
        }
        public string RequestResumeSourceConnection(string id){id=ConnectionId(id);return EnqueueOperation("SourceCheck",(db,t,p)=>OwnSourceConnection(()=>CheckConnection(db,id,null,null,t,p)));}
        public string RequestApplySourceConnection(string id,bool acceptCandidatesAndMissing){id=ConnectionId(id);return EnqueueOperation("SourceApply",(db,t,p)=>OwnSourceConnection(()=>{
            t.ThrowIfCancellationRequested();WaitWrite(w=>{Catalog.PreviewTransaction(w,()=>{var s=Catalog.ConnectionStatus(w,id,false);if(s.State=="applied")return;if(s.State!="ready" || s.Failed!=0 || s.Full+s.Candidates==0)throw new InvalidOperationException("The source check must finish with at least one match and no failed or mismatched files before applying.");if((s.Candidates>0 || s.Missing>0) && !acceptCandidatesAndMissing)throw new InvalidOperationException("Explicitly accept quick candidate matches and missing files before applying this connection. Candidates are not full-file proof.");
                if(Convert.ToInt64(w.Scalar("SELECT identity_revision FROM source_connections WHERE id=?",id))!=Convert.ToInt64(w.Scalar("SELECT COALESCE((SELECT revision FROM source_identity_versions WHERE root_id=?),0)",s.RootId)))throw new InvalidOperationException("Source identities changed after this check. Discard it and check again before applying.");string head=(string)w.Scalar("SELECT base_head FROM source_connections WHERE id=?",id),current=(string)w.Scalar("SELECT connection_id FROM root_source_heads WHERE root_id=?",s.RootId)??"";if(head!=current)throw new InvalidOperationException("This source binding changed after checking; discard the check and check again.");
                if(w.Scalar("SELECT 1 FROM source_roots WHERE id<>? AND path_key=? LIMIT 1",s.RootId,Paths.Key(s.Path))!=null)throw new InvalidOperationException("Another recorded root already uses this location; its reviews cannot be silently merged.");
                if(current.Length>0)w.Execute("UPDATE source_connections SET state='superseded' WHERE id=?",current);w.Execute("UPDATE source_connections SET state='applied',applied_at=? WHERE id=?",Catalog.Now(),id);w.Execute("INSERT INTO root_source_heads VALUES(?,?) ON CONFLICT(root_id) DO UPDATE SET connection_id=excluded.connection_id",s.RootId,id);Catalog.Bump(w);
            });return null;});return "Source connection committed. Recorded identities, reviews, Evidence and scan manifests are preserved.";
        }));}
        public string RequestDiscardSourceConnection(string id){id=ConnectionId(id);return EnqueueOperation("SourceDiscard",(db,t,p)=>OwnSourceConnection(()=>{
            WaitWrite(w=>{if(w.Scalar("SELECT 1 FROM root_source_heads WHERE connection_id=?",id)!=null)throw new InvalidOperationException("An active connection cannot be discarded. Check a replacement location first.");w.Execute("UPDATE source_connections SET state='discarding' WHERE id=?",id);return null;});long done=0;while(true){t.ThrowIfCancellationRequested();long count=(long)WaitWrite(w=>{return (long)w.Execute("DELETE FROM source_connection_files WHERE rowid IN(SELECT rowid FROM source_connection_files WHERE connection_id=? LIMIT 200)",id);});done+=count;p(done,-1,"check rows removed");if(count==0)break;}WaitWrite(w=>{w.Execute("DELETE FROM source_connections WHERE id=? AND state='discarding'",id);return null;});return "Unapplied source check discarded. Media and saved reviews are unchanged.";
        }));}
        object CheckConnection(SqliteConnection reader,string id,string root,string path,CancellationToken token,Action<long,long,string> progress){
            if(root!=null)while(true){token.ThrowIfCancellationRequested();string obsolete=(string)reader.Scalar("SELECT id FROM source_connections WHERE root_id=? AND state='superseded' LIMIT 1",root);if(obsolete==null)break;long removed=(long)WaitWrite(w=>(long)w.Execute("DELETE FROM source_connection_files WHERE rowid IN(SELECT rowid FROM source_connection_files WHERE connection_id=? LIMIT 200)",obsolete));if(removed==0)WaitWrite(w=>{w.Execute("DELETE FROM source_connections WHERE id=? AND state='superseded'",obsolete);return null;});else progress(removed,-1,"older check rows removed");}
            token.ThrowIfCancellationRequested();if(root!=null)WaitWrite(w=>{Catalog.PreviewTransaction(w,()=>{
                if(w.Scalar("SELECT 1 FROM roots WHERE id=?",root)==null)throw new InvalidOperationException("Recorded root is unavailable.");if(Convert.ToInt64(w.Scalar("SELECT COUNT(*) FROM source_connections WHERE state IN('checking','interrupted','ready','discarding')"))>=20)throw new InvalidOperationException("Resume or discard an earlier source check; at most20 unfinished checks are retained.");
                if(w.Scalar("SELECT 1 FROM source_connections WHERE root_id=? AND state IN('checking','interrupted','ready','discarding')",root)!=null)throw new InvalidOperationException("Resume or discard the earlier check for this source first.");
                long ceiling=Convert.ToInt64(w.Scalar("SELECT COALESCE(MAX(rowid),0) FROM occurrences WHERE root_id=?",root)),total=Convert.ToInt64(w.Scalar("SELECT COUNT(*) FROM occurrences o WHERE root_id=? AND rowid<=? AND "+Catalog.ConnectionEligible,root,ceiling));string head=(string)w.Scalar("SELECT connection_id FROM root_source_heads WHERE root_id=?",root)??"";
                w.Execute("INSERT INTO source_connections(id,root_id,path,path_key,base_head,identity_revision,state,created_at,ceiling,total) VALUES(?,?,?,?,?,?,'checking',?,?,?)",id,root,path,Paths.Key(path),head,Convert.ToInt64(w.Scalar("SELECT COALESCE((SELECT revision FROM source_identity_versions WHERE root_id=?),0)",root)),Catalog.Now(),ceiling,total);
            });return null;});
            var state=Catalog.ConnectionStatus(reader,id,false);if(state.State=="ready" || state.State=="applied")return ConnectionSummary(state);if(state.State!="checking" && state.State!="interrupted")throw new InvalidOperationException("This check cannot be resumed.");root=state.RootId;path=state.Path;WaitWrite(w=>{w.Execute("UPDATE source_connections SET state='checking' WHERE id=?",id);return null;});byte[] buffer=new byte[1024*1024];
            try{while(true){token.ThrowIfCancellationRequested();var rows=reader.Query(Catalog.ConnectionNextSql,new object[]{id},1);if(rows.Count==0)break;var r=rows[0];FileRecord match=null;string outcome="failed",error="",fullPath="";
                try{fullPath=Catalog.PreviewSourcePath(path,(string)r[3]);var references=reader.Query(Catalog.ConnectionIdentitySql,new object[]{root,r[2],r[1]},2);if(references.Count!=1)throw new InvalidDataException("This location has conflicting current identities; resolve them before reconnecting.");var reference=references[0];if((long)reference[4]!=(long)r[4])throw new InvalidDataException("The current content and recorded location sizes disagree; rescan before reconnecting.");FingerprintPolicy policy;
                    if((string)reference[0]=="sha256" && (long)reference[1]==1 && ((string)reference[2]).Length==64)policy=FingerprintPolicy.Full();else policy=Verification.CandidatePolicy(new object[]{null,null,reference[0],null,null,null,reference[1],reference[2],reference[3],reference[4]});
                    for(int attempt=0;;attempt++)try{
                        token.ThrowIfCancellationRequested();using(var stream=new FileStream(Paths.Io(fullPath),FileMode.Open,FileAccess.Read,FileShare.Read,65536,FileOptions.Asynchronous|FileOptions.SequentialScan)){
                            Paths.OpenedSourceWithinRoot(stream,path);if(FileAccessNative.Stamp(stream).Size!=(long)r[4])throw new InvalidDataException("Replacement size differs from the saved content.");long read=0;match=FileAccessNative.FingerprintOpened(fullPath,stream,new FileRecord(),buffer,token,n=>{read+=n;progress(read,-1,"source bytes read");},0,policy);
                        }break;
                    }catch(Exception e){if(e is OperationCanceledException || !FileAccessNative.Transient(e) || attempt>=3)throw;WaitWrite(w=>{Catalog.Log(w,"retry","Source check",fullPath,"Retry "+(attempt+1)+"/3: "+e.Message);return null;});if(token.WaitHandle.WaitOne(attempt==0 ? 250 : attempt==1 ? 1000 : 3000))token.ThrowIfCancellationRequested();}
                    if(match==null || match.Size!=(long)r[4] || !String.Equals(match.Hash,((string)reference[0]=="sha256" ? "" : "q2:")+(string)reference[2],StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Replacement fingerprint differs from the saved content. It cannot inherit this review.");outcome=match.Algorithm=="sha256" ? "full" : "candidate";
                }catch(OperationCanceledException){throw;}catch(Exception e){match=null;outcome=e is FileNotFoundException || e is DirectoryNotFoundException ? "missing" : "failed";error=e.GetType().Name+": "+e.Message;if(error.Length>2048)error=error.Substring(0,2048);}
                token.ThrowIfCancellationRequested();WaitWrite(w=>{Catalog.PreviewTransaction(w,()=>{
                    w.Execute("INSERT INTO source_connection_files VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",id,r[1],r[2],r[3],r[4],r[5],r[6],match==null ? null : (object)match.Size,match==null ? null : (object)match.ModifiedTicks,match==null ? null : match.FileIdentity,outcome,error);
                    string column=outcome=="full" ? "full_count" : outcome=="candidate" ? "candidate_count" : outcome=="missing" ? "missing_count" : "failed_count";w.Execute("UPDATE source_connections SET cursor=?,"+column+"="+column+"+1 WHERE id=?",r[0],id);if(error.Length>0)Catalog.Log(w,"warning","Source check",fullPath,error);
                });return null;},4096+((string)r[1]).Length*2L+((string)r[3]).Length*2L);state=Catalog.ConnectionStatus(reader,id,false);progress(state.Full+state.Candidates+state.Missing+state.Failed,state.Total,"recorded files checked");
            }WaitWrite(w=>{w.Execute("UPDATE source_connections SET state='ready' WHERE id=?",id);return null;});return ConnectionSummary(Catalog.ConnectionStatus(reader,id,false));
            }catch{if(!faulted && !stop.IsCancellationRequested)try{WaitWrite(w=>{w.Execute("UPDATE source_connections SET state='interrupted' WHERE id=? AND state='checking'",id);return null;});}catch{}throw;}
        }
        static string ConnectionSummary(SourceConnection s){return "Source check: "+s.Full+" full matches, "+s.Candidates+" quick candidates, "+s.Missing+" missing, "+s.Failed+" failed. Review Sources before applying.";}
    }
}
